import React, { useState } from 'react';

function Books() {
    const [books, setBooks] = useState([]);
    const [title, setTitle] = useState('');
    const [author, setAuthor] = useState('');

    function handleAddBook(e) {
        e.preventDefault();
        if (!title.trim() || !author.trim()) return;

        const newBook = {
            id: Date.now(),
            title,
            author,
            read: false
        };

        setBooks([...books, newBook]);
        setTitle('');
        setAuthor('');
    }

    function toggleRead(id) {
        setBooks(
            books.map(book =>
                book.id === id ? { ...book, read: !book.read } : book
            )
        );
    }

    function removeBook(id) {
        setBooks(books.filter(book => book.id !== id));
    }

    return (
        <>
           <h1> have food ,pay,then split</h1>
            
            
            <section>
                <button className='btn btn-white '>add friend</button>
            </section>

        
            <section className='container'>
                {books.map(book => (
                    <div key={book.id} className='row align-items-center border p-3 mb-2'>
                        <div className="col-auto">
                            <input
                                type="checkbox"
                                checked={book.read}
                                onChange={() => toggleRead(book.id)}
                            />
                        </div>
                        <div className="col-md-3">
                            <h5 className='mb-0'>{book.title}</h5>
                            <small className='text-muted'>{book.author}</small>
                        </div>
                        <div className="col-md-3">
                            <button
                                className={`btn ${book.read ? 'btn-secondary' : 'btn-success'} w-100`}
                                onClick={() => toggleRead(book.id)}
                            >
                                {book.read ? 'Mark as Unread' : 'Mark as Read'}
                            </button>
                        </div>
                        <div className="col-md-3">
                            <button
                                className='btn btn-danger w-100'
                                onClick={() => removeBook(book.id)}
                            >
                                Remove from List
                            </button>
                        </div>
                    </div>
                ))}
                {books.length === 0 && (
                    <div className="text-center text-muted">No books added yet.</div>
                )}
            </section>
        </>
    );
}

export default Books;
